select substring(group_concat(concat(s.nama, ': ', left(trim(trailing ';' from k.jawaban), 150)) order by s.saksi_pihak_ke, s.urutan, k.urutan_pertanyaan separator '; '), 1, 900) as data from aps_badilag.abt_keterangan_saksi k join perkara_pihak5 s on s.id = k.saksi_id where k.perkara_id = #perkara_id# and k.pertanyaan regexp 'harta|barang|tanah|kendaraan|motor|mobil|kebun|sertifikat|rumah (milik|bersama)'